70	bool ReadBufferFromS3::nextImpl()
71	{
72	    if (read_until_position)
73	    {
74	        if (read_until_position == offset)
75	            return false;
76	
77	        if (read_until_position < offset)
78	            throw Exception(ErrorCodes::LOGICAL_ERROR, "Attempt to read beyond right offset ({} > {})", offset, read_until_position - 1);
79	    }
80	
81	    bool next_result = false;
82	
83	    if (impl)
84	    {
85	        if (use_external_buffer)
86	        {
87	            /**
88	            * use_external_buffer -- means we read into the buffer which
89	            * was passed to us from somewhere else. We do not check whether
90	            * previously returned buffer was read or not (no hasPendingData() check is needed),
91	            * because this branch means we are prefetching data,
92	            * each nextImpl() call we can fill a different buffer.
93	            */
94	            impl->set(internal_buffer.begin(), internal_buffer.size());
95	            assert(working_buffer.begin() != nullptr);
96	            assert(!internal_buffer.empty());
97	        }
98	        else
99	        {
100	            /**
101	            * impl was initialized before, pass position() to it to make
102	            * sure there is no pending data which was not read.
103	            */
104	            impl->position() = position();
105	            assert(!impl->hasPendingData());
106	        }
107	    }
108	
109	    size_t sleep_time_with_backoff_milliseconds = 100;
110	    for (size_t attempt = 0; (attempt < max_single_read_retries) && !next_result; ++attempt)
111	    {
112	        Stopwatch watch;
113	        try
114	        {
115	            if (!impl)
116	            {
117	                impl = initialize();
118	
119	                if (use_external_buffer)
120	                {
121	                    impl->set(internal_buffer.begin(), internal_buffer.size());
122	                    assert(working_buffer.begin() != nullptr);
123	                    assert(!internal_buffer.empty());
124	                }
125	                else
126	                {
127	                    /// use the buffer returned by `impl`
128	                    BufferBase::set(impl->buffer().begin(), impl->buffer().size(), impl->offset());
129	                }
130	            }
131	
132	            /// Try to read a next portion of data.
133	            next_result = impl->next();
134	            watch.stop();
135	            ProfileEvents::increment(ProfileEvents::ReadBufferFromS3Microseconds, watch.elapsedMicroseconds());
136	            break;
137	        }
138	        catch (const Exception & e)
139	        {
140	            watch.stop();
141	            ProfileEvents::increment(ProfileEvents::ReadBufferFromS3Microseconds, watch.elapsedMicroseconds());
142	            ProfileEvents::increment(ProfileEvents::ReadBufferFromS3RequestsErrors, 1);
143	
144	            LOG_DEBUG(
145	                log,
146	                "Caught exception while reading S3 object. Bucket: {}, Key: {}, Version: {}, Offset: {}, Attempt: {}, Message: {}",
147	                bucket,
148	                key,
149	                version_id.empty() ? "Latest" : version_id,
150	                getPosition(),
151	                attempt,
152	                e.message());
153	
154	            if (attempt + 1 == max_single_read_retries)
155	                throw;
156	
157	            /// Pause before next attempt.
158	            sleepForMilliseconds(sleep_time_with_backoff_milliseconds);
159	            sleep_time_with_backoff_milliseconds *= 2;
160	
161	            /// Try to reinitialize `impl`.
162	            impl.reset();
163	        }
164	    }
165	
166	    if (!next_result)
167	        return false;
168	
169	    BufferBase::set(impl->buffer().begin(), impl->buffer().size(), impl->offset());
170	
171	    ProfileEvents::increment(ProfileEvents::ReadBufferFromS3Bytes, working_buffer.size());
172	    offset += working_buffer.size();
173	    if (read_settings.remote_throttler)
174	        read_settings.remote_throttler->add(working_buffer.size());
175	
176	    return true;
177	}
