180	off_t ReadBufferFromS3::seek(off_t offset_, int whence)
181	{
182	    if (offset_ == offset && whence == SEEK_SET)
183	        return offset;
184	
185	    if (impl && restricted_seek)
186	        throw Exception(
187	            ErrorCodes::CANNOT_SEEK_THROUGH_FILE,
188	            "Seek is allowed only before first read attempt from the buffer (current offset: {}, new offset: {}, reading until position: {}, available: {})",
189	            offset, offset_, read_until_position, available());
190	
191	    if (whence != SEEK_SET)
192	        throw Exception("Only SEEK_SET mode is allowed.", ErrorCodes::CANNOT_SEEK_THROUGH_FILE);
193	
194	    if (offset_ < 0)
195	        throw Exception("Seek position is out of bounds. Offset: " + std::to_string(offset_), ErrorCodes::SEEK_POSITION_OUT_OF_BOUND);
196	
197	    if (!restricted_seek)
198	    {
199	        if (!working_buffer.empty()
200	            && static_cast<size_t>(offset_) >= offset - working_buffer.size()
201	            && offset_ < offset)
202	        {
203	            pos = working_buffer.end() - (offset - offset_);
204	            assert(pos >= working_buffer.begin());
205	            assert(pos <= working_buffer.end());
206	
207	            return getPosition();
208	        }
209	
210	        auto position = getPosition();
211	        if (offset_ > position)
212	        {
213	            size_t diff = offset_ - position;
214	            if (diff < read_settings.remote_read_min_bytes_for_seek)
215	            {
216	                ignore(diff);
217	                return offset_;
218	            }
219	        }
220	
221	        resetWorkingBuffer();
222	        if (impl)
223	        {
224	            ProfileEvents::increment(ProfileEvents::ReadBufferSeekCancelConnection);
225	            impl.reset();
226	        }
227	    }
228	
229	    offset = offset_;
230	    return offset;
231	}
