265	{
266	    Aws::S3::Model::GetObjectRequest req;
267	    req.SetBucket(bucket);
268	    req.SetKey(key);
269	    if (!version_id.empty())
270	    {
271	        req.SetVersionId(version_id);
272	    }
273	
274	    /**
275	     * If remote_filesystem_read_method = 'threadpool', then for MergeTree family tables
276	     * exact byte ranges to read are always passed here.
277	     */
278	    if (read_until_position)
279	    {
280	        if (offset >= read_until_position)
281	            throw Exception(ErrorCodes::LOGICAL_ERROR, "Attempt to read beyond right offset ({} > {})", offset, read_until_position - 1);
282	
283	        req.SetRange(fmt::format("bytes={}-{}", offset, read_until_position - 1));
284	        LOG_TEST(
285	            log,
286	            "Read S3 object. Bucket: {}, Key: {}, Version: {}, Range: {}-{}",
287	            bucket,
288	            key,
289	            version_id.empty() ? "Latest" : version_id,
290	            offset,
291	            read_until_position - 1);
292	    }
293	    else
294	    {
295	        if (offset)
296	            req.SetRange(fmt::format("bytes={}-", offset));
297	        LOG_TEST(
298	            log,
299	            "Read S3 object. Bucket: {}, Key: {}, Version: {}, Offset: {}",
300	            bucket,
301	            key,
302	            version_id.empty() ? "Latest" : version_id,
303	            offset);
304	    }
305	
306	    ProfileEvents::increment(for_disk_s3 ? ProfileEvents::DiskS3GetObject : ProfileEvents::S3GetObject);
307	
308	    Aws::S3::Model::GetObjectOutcome outcome = client_ptr->GetObject(req);
309	
310	    if (outcome.IsSuccess())
311	    {
312	        read_result = outcome.GetResultWithOwnership();
313	        size_t buffer_size = use_external_buffer ? 0 : read_settings.remote_fs_buffer_size;
314	        return std::make_unique<ReadBufferFromIStream>(read_result.GetBody(), buffer_size);
315	    }
316	    else
317	        throw Exception(outcome.GetError().GetMessage(), ErrorCodes::S3_ERROR);
