90	void WriteBufferFromS3::nextImpl()
91	{
92	    if (!offset())
93	        return;
94	
95	    /// Buffer in a bad state after exception
96	    if (temporary_buffer->tellp() == -1)
97	        allocateBuffer();
98	
99	    size_t size = offset();
100	    temporary_buffer->write(working_buffer.begin(), size);
101	
102	    ThreadGroupStatusPtr running_group = CurrentThread::isInitialized() && CurrentThread::get().getThreadGroup()
103	            ? CurrentThread::get().getThreadGroup()
104	            : MainThreadStatus::getInstance().getThreadGroup();
105	
106	    if (cacheEnabled())
107	    {
108	        auto cache_key = cache->hash(key);
109	
110	        file_segments_holder.emplace(cache->setDownloading(cache_key, current_download_offset, size, /* is_persistent */false));
111	        current_download_offset += size;
112	
113	        size_t remaining_size = size;
114	        auto & file_segments = file_segments_holder->file_segments;
115	        for (auto file_segment_it = file_segments.begin(); file_segment_it != file_segments.end(); ++file_segment_it)
116	        {
117	            auto & file_segment = *file_segment_it;
118	            size_t current_size = std::min(file_segment->range().size(), remaining_size);
119	            remaining_size -= current_size;
120	
121	            if (file_segment->reserve(current_size))
122	            {
123	                file_segment->writeInMemory(working_buffer.begin(), current_size);
124	            }
125	            else
126	            {
127	                for (auto reset_segment_it = file_segment_it; reset_segment_it != file_segments.end(); ++reset_segment_it)
128	                    (*reset_segment_it)->complete(FileSegment::State::PARTIALLY_DOWNLOADED_NO_CONTINUATION);
129	                file_segments.erase(file_segment_it, file_segments.end());
130	                break;
131	            }
132	        }
133	    }
134	
135	    ProfileEvents::increment(ProfileEvents::WriteBufferFromS3Bytes, offset());
136	    last_part_size += offset();
137	    if (write_settings.remote_throttler)
138	        write_settings.remote_throttler->add(offset());
139	
140	    /// Data size exceeds singlepart upload threshold, need to use multipart upload.
141	    if (multipart_upload_id.empty() && last_part_size > s3_settings.max_single_part_upload_size)
142	        createMultipartUpload();
143	
144	    if (!multipart_upload_id.empty() && last_part_size > upload_part_size)
145	    {
146	        writePart();
147	
148	        allocateBuffer();
149	        file_segments_holder.reset();
150	    }
151	
152	    waitForReadyBackGroundTasks();
153	}
