243	void WriteBufferFromS3::writePart()
244	{
245	    auto size = temporary_buffer->tellp();
246	
247	    LOG_TRACE(log, "Writing part. Bucket: {}, Key: {}, Upload_id: {}, Size: {}", bucket, key, multipart_upload_id, size);
248	
249	    if (size < 0)
250	    {
251	        LOG_WARNING(log, "Skipping part upload. Buffer is in bad state, it means that we have tried to upload something, but got an exception.");
252	        return;
253	    }
254	
255	    if (size == 0)
256	    {
257	        LOG_TRACE(log, "Skipping writing part. Buffer is empty.");
258	        return;
259	    }
260	
261	    if (part_tags.size() == S3_WARN_MAX_PARTS)
262	    {
263	        // Don't throw exception here by ourselves but leave the decision to take by S3 server.
264	        LOG_WARNING(log, "Maximum part number in S3 protocol has reached (too many parts). Server may not accept this whole upload.");
265	    }
266	
267	    if (schedule)
268	    {
269	        UploadPartTask * task = nullptr;
270	        int part_number;
271	        {
272	            std::lock_guard lock(bg_tasks_mutex);
273	            task = &upload_object_tasks.emplace_back();
274	            ++num_added_bg_tasks;
275	            part_number = num_added_bg_tasks;
276	        }
277	
278	        fillUploadRequest(task->req, part_number);
279	
280	        if (file_segments_holder)
281	        {
282	            task->cache_files.emplace(std::move(*file_segments_holder));
283	            file_segments_holder.reset();
284	        }
285	
286	        schedule([this, task]()
287	        {
288	            try
289	            {
290	                processUploadRequest(*task);
291	            }
292	            catch (...)
293	            {
294	                task->exception = std::current_exception();
295	            }
296	
297	            try
298	            {
299	                finalizeCacheIfNeeded(task->cache_files);
300	            }
301	            catch (...)
302	            {
303	                tryLogCurrentException(__PRETTY_FUNCTION__);
304	            }
305	
306	            {
307	                std::lock_guard lock(bg_tasks_mutex);
308	                task->is_finised = true;
309	                ++num_finished_bg_tasks;
310	
311	                /// Notification under mutex is important here.
312	                /// Otherwise, WriteBuffer could be destroyed in between
313	                /// Releasing lock and condvar notification.
314	                bg_tasks_condvar.notify_one();
315	            }
316	        });
317	    }
318	    else
319	    {
320	        UploadPartTask task;
321	        fillUploadRequest(task.req, part_tags.size() + 1);
322	        if (file_segments_holder)
323	        {
324	            task.cache_files.emplace(std::move(*file_segments_holder));
325	            file_segments_holder.reset();
326	        }
327	        processUploadRequest(task);
328	        part_tags.push_back(task.tag);
329	        finalizeCacheIfNeeded(task.cache_files);
330	    }
331	}
