333	void WriteBufferFromS3::fillUploadRequest(Aws::S3::Model::UploadPartRequest & req, int part_number)
334	{
335	    req.SetBucket(bucket);
336	    req.SetKey(key);
337	    req.SetPartNumber(part_number);
