363	void WriteBufferFromS3::completeMultipartUpload()
364	{
365	    LOG_TRACE(log, "Completing multipart upload. Bucket: {}, Key: {}, Upload_id: {}, Parts: {}", bucket, key, multipart_upload_id, part_tags.size());
366	
367	    if (part_tags.empty())
368	        throw Exception("Failed to complete multipart upload. No parts have uploaded", ErrorCodes::S3_ERROR);
369	
370	    Aws::S3::Model::CompleteMultipartUploadRequest req;
371	    req.SetBucket(bucket);
372	    req.SetKey(key);
373	    req.SetUploadId(multipart_upload_id);
374	
375	    Aws::S3::Model::CompletedMultipartUpload multipart_upload;
376	    for (size_t i = 0; i < part_tags.size(); ++i)
377	    {
378	        Aws::S3::Model::CompletedPart part;
379	        multipart_upload.AddParts(part.WithETag(part_tags[i]).WithPartNumber(i + 1));
380	    }
381	
382	    req.SetMultipartUpload(multipart_upload);
383	
384	    ProfileEvents::increment(for_disk_s3 ? ProfileEvents::DiskS3CompleteMultipartUpload : ProfileEvents::S3CompleteMultipartUpload);
385	
386	    auto outcome = client_ptr->CompleteMultipartUpload(req);
387	
388	    if (outcome.IsSuccess())
389	        LOG_TRACE(log, "Multipart upload has completed. Bucket: {}, Key: {}, Upload_id: {}, Parts: {}", bucket, key, multipart_upload_id, part_tags.size());
390	    else
391	    {
392	        throw Exception(ErrorCodes::S3_ERROR, "{} Tags:{}",
393	            outcome.GetError().GetMessage(),
394	            fmt::join(part_tags.begin(), part_tags.end(), " "));
395	    }
396	}
