398	void WriteBufferFromS3::makeSinglepartUpload()
399	{
400	    auto size = temporary_buffer->tellp();
401	    bool with_pool = static_cast<bool>(schedule);
402	
403	    LOG_TRACE(log, "Making single part upload. Bucket: {}, Key: {}, Size: {}, WithPool: {}", bucket, key, size, with_pool);
404	
405	    if (size < 0)
406	    {
407	        LOG_WARNING(log, "Skipping single part upload. Buffer is in bad state, it mean that we have tried to upload something, but got an exception.");
408	        return;
409	    }
410	
411	    if (schedule)
412	    {
413	        put_object_task = std::make_unique<PutObjectTask>();
414	
415	        fillPutRequest(put_object_task->req);
416	        if (file_segments_holder)
417	        {
418	            put_object_task->cache_files.emplace(std::move(*file_segments_holder));
419	            file_segments_holder.reset();
420	        }
421	
422	        schedule([this]()
423	        {
424	            try
425	            {
426	                processPutRequest(*put_object_task);
427	            }
428	            catch (...)
429	            {
430	                put_object_task->exception = std::current_exception();
431	            }
432	
433	            try
434	            {
435	                finalizeCacheIfNeeded(put_object_task->cache_files);
436	            }
437	            catch (...)
438	            {
439	                tryLogCurrentException(__PRETTY_FUNCTION__);
440	            }
441	
442	            {
443	                std::lock_guard lock(bg_tasks_mutex);
444	                put_object_task->is_finised = true;
445	
446	                /// Notification under mutex is important here.
447	                /// Othervies, WriteBuffer could be destroyed in between
448	                /// Releasing lock and condvar notification.
449	                bg_tasks_condvar.notify_one();
450	            }
451	        });
452	    }
453	    else
454	    {
455	        PutObjectTask task;
456	        fillPutRequest(task.req);
457	        if (file_segments_holder)
458	        {
459	            task.cache_files.emplace(std::move(*file_segments_holder));
460	            file_segments_holder.reset();
461	        }
462	        processPutRequest(task);
463	        finalizeCacheIfNeeded(task.cache_files);
464	    }
465	}
