492	void WriteBufferFromS3::finalizeCacheIfNeeded(std::optional<FileSegmentsHolder> & file_segments_holder)
493	{
494	    if (!file_segments_holder)
495	        return;
496	
497	    auto & file_segments = file_segments_holder->file_segments;
498	    for (auto file_segment_it = file_segments.begin(); file_segment_it != file_segments.end();)
499	    {
500	        try
501	        {
502	            size_t size = (*file_segment_it)->finalizeWrite();
503	            file_segment_it = file_segments.erase(file_segment_it);
504	
505	            ProfileEvents::increment(ProfileEvents::CachedReadBufferCacheWriteBytes, size);
506	        }
507	        catch (...)
508	        {
509	            tryLogCurrentException(__PRETTY_FUNCTION__);
510	        }
511	    }
512	}
