514	void WriteBufferFromS3::waitForReadyBackGroundTasks()
515	{
516	    if (schedule)
517	    {
518	        std::lock_guard lock(bg_tasks_mutex);
519	        {
520	            while (!upload_object_tasks.empty() && upload_object_tasks.front().is_finised)
521	            {
522	                auto & task = upload_object_tasks.front();
523	                auto exception = task.exception;
524	                auto tag = std::move(task.tag);
525	                upload_object_tasks.pop_front();
526	
527	                if (exception)
528	                {
529	                    waitForAllBackGroundTasks();
530	                    std::rethrow_exception(exception);
531	                }
532	
533	                part_tags.push_back(tag);
534	            }
535	        }
536	    }
537	}
