539	void WriteBufferFromS3::waitForAllBackGroundTasks()
540	{
541	    if (schedule)
542	    {
543	        std::unique_lock lock(bg_tasks_mutex);
544	        bg_tasks_condvar.wait(lock, [this]() { return num_added_bg_tasks == num_finished_bg_tasks; });
545	
546	        while (!upload_object_tasks.empty())
547	        {
548	            auto & task = upload_object_tasks.front();
549	            if (task.exception)
550	                std::rethrow_exception(task.exception);
551	
552	            part_tags.push_back(task.tag);
553	
554	            upload_object_tasks.pop_front();
555	        }
556	
557	        if (put_object_task)
558	        {
559	            bg_tasks_condvar.wait(lock, [this]() { return put_object_task->is_finised; });
560	            if (put_object_task->exception)
561	                std::rethrow_exception(put_object_task->exception);
562	        }
563	    }
564	}
